drop policy if exists actors_member_select on public.actors;
create policy actors_member_select on public.actors for select to authenticated using (exists (select 1 from public.campaign_members m where m.campaign_id = actors.campaign_id and m.user_id = auth.uid()) or exists (select 1 from public.campaigns c where c.id = actors.campaign_id and c.owner_id = auth.uid()));
drop policy if exists actors_owner_write on public.actors;
create policy actors_owner_write on public.actors for all to authenticated using (owner_id = auth.uid() or exists (select 1 from public.campaigns c where c.id = actors.campaign_id and c.owner_id = auth.uid()) or exists (select 1 from public.campaign_members m where m.campaign_id = actors.campaign_id and m.user_id = auth.uid() and m.role = 'gm')) with check (owner_id = auth.uid() or exists (select 1 from public.campaigns c where c.id = actors.campaign_id and c.owner_id = auth.uid()) or exists (select 1 from public.campaign_members m where m.campaign_id = actors.campaign_id and m.user_id = auth.uid() and m.role = 'gm'));
